import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.BP2ycr77.js";const g=JSON.parse('{"title":"Évaluation 2 — Rapport de faisabilité technique : proposition technique","description":"","frontmatter":{"title":"Évaluation 2 — Rapport de faisabilité technique : proposition technique","aside":false},"headers":[],"relativePath":"evaluations/evaluation-2.md","filePath":"evaluations/evaluation-2.md"}'),n={name:"evaluations/evaluation-2.md"};function l(r,e,o,u,c,d){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="evaluation-2-—-rapport-de-faisabilite-technique-proposition-technique" tabindex="-1">Évaluation 2 — Rapport de faisabilité technique : proposition technique <a class="header-anchor" href="#evaluation-2-—-rapport-de-faisabilite-technique-proposition-technique" aria-label="Permalink to &quot;Évaluation 2 — Rapport de faisabilité technique : proposition technique&quot;">​</a></h1><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>En bref</strong><br><ul class="list-disc pl-5"><li><strong>Pondération :</strong> 20 % de la note finale, dont 10 % de l&#39;évaluation pour la qualité du français.</li><li><strong>Équipe :</strong> votre équipe de la session, 2 ou 3 personnes.</li><li><strong>Remise :</strong> sur LÉA, au plus tard le <strong>mercredi 9 décembre, 18 h 30</strong> (début de la séance 11).</li><li><strong>Format :</strong> le rapport <strong>complet</strong> (parties 1 et 2) dans un seul fichier Word (<code>.docx</code>) nommé <code>eval2-equipeN-nom1-nom2-nom3.docx</code>.</li><li><strong>Longueur :</strong> de 8 à 12 pages pour la partie 2, sans compter les annexes.</li><li><strong>Retard :</strong> 10 % par jour; aucun travail accepté après 7 jours.</li></ul><a href="./../fiches/eval2-gabarit-proposition.docx" download><strong>Télécharger le gabarit de la partie 2 (Word)</strong></a></div><hr><h2 id="la-mise-en-situation" tabindex="-1">La mise en situation <a class="header-anchor" href="#la-mise-en-situation" aria-label="Permalink to &quot;La mise en situation&quot;">​</a></h2><p>Votre évaluation technique a fait le portrait du projet d&#39;<a href="./../mandat/">Aventure Saint-Maurice</a> : ce qu&#39;il exige, ce qui le contraint, ce qui pourrait mal tourner et les technologies qui existent. Mélanie l&#39;a lue. Sa question, maintenant, est simple :</p><blockquote><p>« Qu&#39;est-ce que vous nous conseillez, combien ça coûte, et est-ce que ce sera prêt pour le 1<sup>er</sup> mars ? »</p></blockquote><p>La <strong>proposition technique</strong> y répond. Elle complète le même document : c&#39;est la <strong>deuxième moitié</strong> du rapport de faisabilité.</p><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Cette fois, vous tranchez.</strong><br> La partie 1 décrivait sans recommander. La partie 2 <strong>choisit</strong> : un outil par question, des formats, des adaptations, un échéancier, un devis et une recommandation finale. Chaque choix s&#39;appuie sur ce que la partie 1 a établi : une exigence, une contrainte, un risque, un essai ou une source. Un choix qui ne renvoie à rien de tout cela est une opinion. </div><hr><h2 id="competence-et-elements-vises" tabindex="-1">Compétence et éléments visés <a class="header-anchor" href="#competence-et-elements-vises" aria-label="Permalink to &quot;Compétence et éléments visés&quot;">​</a></h2><p><strong>HK29 — Évaluer la faisabilité technique d&#39;un projet</strong></p><ul><li>Élément 4 : proposer des moyens techniques.</li><li>Élément 5 : rédiger un rapport de faisabilité technique (seconde partie).</li></ul><hr><h2 id="le-lecteur" tabindex="-1">Le lecteur <a class="header-anchor" href="#le-lecteur" aria-label="Permalink to &quot;Le lecteur&quot;">​</a></h2><p>Toujours <strong>Mélanie Gauthier</strong>, avec Patrick Lavoie. Mêmes règles qu&#39;à l&#39;évaluation 1 : chaque terme technique est expliqué la première fois ou évité, les tableaux résument et le texte dit ce qu&#39;ils veulent dire pour l&#39;entreprise.</p><p>Une nouveauté : Mélanie va <strong>prendre des décisions</strong> à partir de ce rapport et le montrer à la MRC pour la subvention. Ce qu&#39;elle doit décider et faire doit donc être écrit noir sur blanc, avec des dates.</p><hr><h2 id="le-contenu-du-rapport" tabindex="-1">Le contenu du rapport <a class="header-anchor" href="#le-contenu-du-rapport" aria-label="Permalink to &quot;Le contenu du rapport&quot;">​</a></h2><h3 id="ce-qui-change-dans-la-partie-1" tabindex="-1">Ce qui change dans la partie 1 <a class="header-anchor" href="#ce-qui-change-dans-la-partie-1" aria-label="Permalink to &quot;Ce qui change dans la partie 1&quot;">​</a></h3><ul><li><strong>La page de titre</strong> : « Rapport de faisabilité technique », sans « Partie 1 », avec la nouvelle date.</li><li><strong>Le résumé</strong> est réécrit pour tout le rapport. Il donne maintenant la <strong>recommandation</strong>, le coût et la date de mise en ligne visée. Toujours une demi-page au maximum.</li><li><strong>La portée (2.3)</strong> : le rapport couvre maintenant aussi les choix, les coûts et l&#39;échéancier.</li><li><strong>Les commentaires</strong> reçus pour l&#39;évaluation 1 sont appliqués dans les sections 1 à 7.</li><li><strong>La section 7</strong> : les questions qui ont reçu une réponse lors de la rencontre avec le client (séance 9) sont marquées comme telles, avec la réponse.</li></ul><h3 id="les-nouvelles-sections" tabindex="-1">Les nouvelles sections <a class="header-anchor" href="#les-nouvelles-sections" aria-label="Permalink to &quot;Les nouvelles sections&quot;">​</a></h3><p>Le gabarit de la partie 2 contient ces sections, avec des consignes dans chacune. Copiez-les dans votre rapport, entre la section 7 et les références.</p><h4 id="_8-les-choix-techniques" tabindex="-1">8. Les choix techniques <a class="header-anchor" href="#_8-les-choix-techniques" aria-label="Permalink to &quot;8. Les choix techniques&quot;">​</a></h4><ul><li><strong>8.1 Les critères de choix</strong> : ce qui compte le plus pour ce client, tiré de vos exigences et de vos contraintes, avec un poids pour chacun (par exemple : Mélanie peut modifier les prix seule, le coût annuel, la gestion des départs à 8 places).</li><li><strong>8.2 Les choix pour les cinq questions</strong> : pour chacune des questions Q1 à Q5, l&#39;outil ou la solution retenu, <strong>pourquoi</strong> (les critères, vos essais, vos sources), ce que vous écartez et pourquoi, et ce qui reste à vérifier. Votre question peut s&#39;appuyer sur vos essais; pour les quatre autres, dites sur quoi repose le choix, et ce qu&#39;un essai devra confirmer avant de s&#39;engager.</li><li><strong>8.3 Comment les outils fonctionnent ensemble</strong> : un schéma simple qui montre le site, la réservation, la décharge, Square, Viator, les courriels et le nom de domaine, et ce qui passe de l&#39;un à l&#39;autre. Les liens qui ne fonctionnent pas, ou qui demandent une manipulation à la main, y sont indiqués.</li></ul><h4 id="_9-les-formats-et-les-regles-de-mise-en-ligne" tabindex="-1">9. Les formats et les règles de mise en ligne <a class="header-anchor" href="#_9-les-formats-et-les-regles-de-mise-en-ligne" aria-label="Permalink to &quot;9. Les formats et les règles de mise en ligne&quot;">​</a></h4><ul><li>Un tableau, par sorte de contenu : le format, la largeur, le poids maximal, l&#39;outil et la règle d&#39;accessibilité à respecter. (Vu à la séance 7 et au Lab 07.)</li><li><strong>Qui</strong> fera ce travail chez le client, avec quel outil, et combien de temps ça lui prendra.</li></ul><h4 id="_10-les-adaptations-proposees" tabindex="-1">10. Les adaptations proposées <a class="header-anchor" href="#_10-les-adaptations-proposees" aria-label="Permalink to &quot;10. Les adaptations proposées&quot;">​</a></h4><ul><li>Pour chaque <strong>contrainte déterminante</strong> (section 4.3) et chaque <strong>risque de la zone rouge</strong> (section 5.3) : l&#39;adaptation que vous proposez et ce qu&#39;elle change pour le client. Exemple : le réseau est faible au quai, donc la liste des participants et de leurs allergies doit pouvoir s&#39;ouvrir sans connexion.</li><li><strong>Ce que vous ne proposez pas</strong> (l&#39;application mobile, le niveau de la rivière en direct, l&#39;ouverture l&#39;hiver…), et pourquoi, ou pour quand.</li></ul><h4 id="_11-le-temps" tabindex="-1">11. Le temps <a class="header-anchor" href="#_11-le-temps" aria-label="Permalink to &quot;11. Le temps&quot;">​</a></h4><ul><li><strong>11.1 Les tâches et l&#39;estimation</strong> : le travail découpé en tâches, chacune estimée en trois chiffres (optimiste, probable, pessimiste), et l&#39;estimation retenue. (Vu à la séance 8.)</li><li><strong>11.2 L&#39;échéancier</strong> : les étapes jusqu&#39;au 1<sup>er</sup> mars 2027, ce qui est livré à chacune, ce que le client doit fournir et quand, et le <strong>coussin</strong> prévu pour les imprévus.</li></ul><h4 id="_12-l-argent" tabindex="-1">12. L&#39;argent <a class="header-anchor" href="#_12-l-argent" aria-label="Permalink to &quot;12. L&#39;argent&quot;">​</a></h4><ul><li><strong>12.1 Les coûts uniques</strong> : la construction (les heures de l&#39;estimation × le taux de Studio Web FC) et ce qui s&#39;achète une seule fois.</li><li><strong>12.2 Les coûts annuels</strong> : les abonnements, le nom de domaine, les commissions, l&#39;entretien.</li><li><strong>12.3 Le total sur trois ans, comparé au budget</strong> : 8 000 $, ou 13 000 $ si la subvention de la MRC est accordée.</li><li><strong>12.4 Trois façons d&#39;entrer dans le budget</strong> : enlever des fonctionnalités, changer d&#39;outil, ou livrer le site en plusieurs étapes, avec ce que chacune fait économiser et ce que le client perd. (Vu à la séance 8.)</li></ul><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Les hypothèses communes</strong><ul class="list-disc pl-5"><li>Studio Web FC facture <strong>75 $ de l&#39;heure</strong>, taxes en sus.</li><li>Les prix sont en <strong>dollars canadiens</strong>. Un prix en dollars américains est converti au taux du jour où vous l&#39;avez lu, indiqué avec sa date et sa source sous le tableau.</li><li>Le volume : environ 2 600 réservations et 9 000 participants par été (document 3 du mandat), sauf si vous justifiez une autre hypothèse.</li></ul></div><h4 id="_13-la-recommandation-finale" tabindex="-1">13. La recommandation finale <a class="header-anchor" href="#_13-la-recommandation-finale" aria-label="Permalink to &quot;13. La recommandation finale&quot;">​</a></h4><ul><li><strong>Le projet est-il faisable ?</strong> Oui, non, ou oui à certaines conditions : dites-le dans la première phrase.</li><li>Le <strong>scénario recommandé</strong>, en une page au plus : ce qui sera en ligne le 1<sup>er</sup> mars, ce qui viendra ensuite, le coût sur trois ans.</li><li><strong>Les conditions</strong> : ce qui doit être vrai pour que ça marche.</li><li><strong>Ce que le client doit décider et faire</strong>, avec qui et avant quand : par exemple récupérer l&#39;accès au nom de domaine, choisir une politique d&#39;annulation, faire traduire la décharge par l&#39;avocat.</li></ul><h4 id="_14-references" tabindex="-1">14. Références <a class="header-anchor" href="#_14-references" aria-label="Permalink to &quot;14. Références&quot;">​</a></h4><p>Toutes les sources des deux parties, en style <a href="https://boite-outils.bib.umontreal.ca/citer/apa?p=5248896">APA 7</a>.</p><h4 id="annexes" tabindex="-1">Annexes <a class="header-anchor" href="#annexes" aria-label="Permalink to &quot;Annexes&quot;">​</a></h4><ul><li><strong>A. Résultats des essais</strong> (évaluation 1, inchangée sauf correction).</li><li><strong>B. Déclaration d&#39;utilisation de l&#39;IA générative</strong>, refaite pour l&#39;évaluation 2.</li><li><strong>C. Contribution des membres</strong>, refaite pour l&#39;évaluation 2, signée par tous.</li><li><strong>D. Le détail de l&#39;estimation</strong>, si votre liste de tâches dépasse 15 lignes dans la section 11.</li></ul><hr><h2 id="l-intelligence-artificielle-generative" tabindex="-1">L&#39;intelligence artificielle générative <a class="header-anchor" href="#l-intelligence-artificielle-generative" aria-label="Permalink to &quot;L&#39;intelligence artificielle générative&quot;">​</a></h2><p>Les mêmes règles qu&#39;à l&#39;<a href="./evaluation-1#l-intelligence-artificielle-generative">évaluation 1</a>. En particulier, l&#39;IA générative ne doit pas <strong>produire les choix, l&#39;estimation ou le devis</strong> : ce sont les analyses que la grille évalue. Déclarez chaque usage dans l&#39;annexe B, refaite pour l&#39;évaluation 2.</p><hr><h2 id="la-grille-d-evaluation" tabindex="-1">La grille d&#39;évaluation <a class="header-anchor" href="#la-grille-d-evaluation" aria-label="Permalink to &quot;La grille d&#39;évaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Critère</th><th style="text-align:left;">Ce qui est évalué</th><th style="text-align:right;">Points</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Organisation et clarté</strong></td><td style="text-align:left;">Un seul document cohérent; résumé réécrit qui donne la recommandation, le coût et la date; tableaux lisibles; texte compréhensible pour une non-spécialiste</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Mise à jour de la partie 1</strong></td><td style="text-align:left;">Commentaires de l&#39;évaluation 1 appliqués; portée et section 7 mises à jour</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Choix techniques</strong></td><td style="text-align:left;">Critères tirés des exigences et des contraintes; chaque choix justifié par les essais ou les sources; solutions écartées expliquées; outils qui fonctionnent ensemble, schéma à l&#39;appui</td><td style="text-align:right;">20</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>Formats et mise en ligne</strong></td><td style="text-align:left;">Format, largeur et poids pour chaque sorte de contenu; règles d&#39;accessibilité; qui fait le travail chez le client</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Adaptations</strong></td><td style="text-align:left;">Réponses concrètes aux contraintes déterminantes et aux risques de la zone rouge; ce qui n&#39;est pas proposé est expliqué</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Temps et échéancier</strong></td><td style="text-align:left;">Tâches complètes, estimation en trois chiffres, coussin, échéancier réaliste pour le 1<sup>er</sup> mars et ce que le client doit fournir</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Coûts sur trois ans</strong></td><td style="text-align:left;">Coûts uniques et annuels, hypothèses indiquées, comparaison au budget, trois options pour y entrer</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Recommandation finale</strong></td><td style="text-align:left;">Claire dès la première phrase, cohérente avec tout le rapport; conditions et décisions du client avec des dates</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Qualité du français</strong></td><td style="text-align:left;">Évaluée sur un extrait d&#39;environ 150 mots de la partie 2 choisi par l&#39;enseignant, selon la Politique du français de la DFCSE</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;"></td><td style="text-align:left;"></td><td style="text-align:left;"><strong>Total</strong></td><td style="text-align:right;"><strong>100</strong></td></tr></tbody></table><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Ce qui fait perdre des points rapidement</strong><ul class="list-disc pl-5"><li>Un choix qui ne renvoie à aucune exigence, contrainte, essai ou source.</li><li>Un outil retenu malgré une limite notée dans la partie 1, sans dire comment on la contourne.</li><li>Un devis sans les coûts annuels, ou avec des dollars américains non convertis.</li><li>Un échéancier qui se termine le 28 février, sans coussin, ou qui oublie ce que le client doit fournir.</li><li>Une fonctionnalité promise qui ne figure ni dans l&#39;estimation ni dans le devis.</li><li>Une recommandation finale qui ne dit pas clairement oui ou non.</li><li>Les annexes B, C ou D manquantes.</li></ul></div><hr><h2 id="le-calendrier-conseille" tabindex="-1">Le calendrier conseillé <a class="header-anchor" href="#le-calendrier-conseille" aria-label="Permalink to &quot;Le calendrier conseillé&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Séance</th><th style="text-align:left;">Date</th><th style="text-align:left;">Ce que vous y faites pour la proposition</th></tr></thead><tbody><tr><td style="text-align:center;">7</td><td style="text-align:left;">11 nov.</td><td style="text-align:left;">Lab 07 : formats et règles de mise en ligne → section 9. Lancer la section 8 à partir de vos tableaux de l&#39;évaluation 1</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;">18 nov.</td><td style="text-align:left;">Estimer le temps et monter le devis → sections 11 et 12. Le rapport de l&#39;évaluation 1 vous est rendu corrigé</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;">25 nov.</td><td style="text-align:left;">Rencontre avec le client : les réponses à vos questions → sections 7, 8 et 10</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;">2 déc.</td><td style="text-align:left;">Appliquer les commentaires de l&#39;évaluation 1; période de questions; écrire la section 13 et le résumé</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;">9 déc.</td><td style="text-align:left;"><strong>Remise</strong> avant 18 h 30</td></tr></tbody></table><hr><h2 id="la-liste-de-verification-avant-la-remise" tabindex="-1">La liste de vérification avant la remise <a class="header-anchor" href="#la-liste-de-verification-avant-la-remise" aria-label="Permalink to &quot;La liste de vérification avant la remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Le rapport est complet, en un seul fichier : parties 1 et 2, table des matières à jour</span></label></li><li><label><input type="checkbox"><span class="check-text">La page de titre, le résumé et la portée (2.3) ont été mis à jour</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque commentaire de l&#39;évaluation 1 a été appliqué</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque choix de la section 8 renvoie à une exigence, une contrainte, un essai ou une source</span></label></li><li><label><input type="checkbox"><span class="check-text">Le schéma de la section 8.3 montre ce qui passe d&#39;un outil à l&#39;autre, et ce qui se fait à la main</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque contrainte déterminante et chaque risque rouge ont leur adaptation (section 10)</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque fonctionnalité promise a ses heures dans l&#39;estimation et son coût dans le devis</span></label></li><li><label><input type="checkbox"><span class="check-text">L&#39;échéancier finit avant le 1<sup>er</sup> mars, avec un coussin, et dit ce que le client doit fournir et quand</span></label></li><li><label><input type="checkbox"><span class="check-text">Les coûts sont en dollars canadiens, sur trois ans, comparés à 8 000 $ et à 13 000 $</span></label></li><li><label><input type="checkbox"><span class="check-text">La première phrase de la section 13 dit si le projet est faisable</span></label></li><li><label><input type="checkbox"><span class="check-text">Le texte a été relu par une autre personne de l&#39;équipe que celle qui l&#39;a écrit, et passé dans un correcteur</span></label></li><li><label><input type="checkbox"><span class="check-text">Les annexes A, B, C (et D au besoin) sont présentes; B et C sont refaites pour l&#39;évaluation 2</span></label></li><li><label><input type="checkbox"><span class="check-text">Le fichier est nommé correctement et déposé sur LÉA avant 18 h 30 le 9 décembre</span></label></li></ul>',52)])])}const h=t(n,[["render",l]]);export{g as __pageData,h as default};
